var rad = Tama.Args.Get(args, "searchRadiusM", 0.1) / 0.3048;
var tf = doc.ActiveProjectLocation.GetTotalTransform(); var inv = tf.Inverse;
var tgts = new List<XYZ>();
foreach (var o in (object[])args["corners"]) { var a = (object[])o; tgts.Add(tf.OfPoint(new XYZ(Convert.ToDouble(a[0])/0.3048, Convert.ToDouble(a[1])/0.3048, 0))); }
var report = new List<object>();
foreach (var o in (object[])args["ids"]) {
  var ce = doc.GetElement(new ElementId(Convert.ToInt32(o))) as CurveElement;
  var c = ce.GeometryCurve; var a = c.GetEndPoint(0); var b = c.GetEndPoint(1);
  Func<XYZ,XYZ> snap = p => { var t = tgts.OrderBy(q => new XYZ(q.X-p.X, q.Y-p.Y, 0).GetLength()).First(); if (new XYZ(t.X-p.X, t.Y-p.Y, 0).GetLength() > rad) throw new Exception("No target corner near an end of " + ce.Id.IntegerValue); return new XYZ(t.X, t.Y, p.Z); };
  var na = snap(a); var nb = snap(b);
  Curve nc;
  if (c is Arc) {
    var mid = c.Evaluate(0.5, true); var cm = (a + b) / 2;
    double sag = (mid - cm).DotProduct(XYZ.BasisZ.CrossProduct((b - a).Normalize()));
    var nm = (na + nb) / 2 + XYZ.BasisZ.CrossProduct((nb - na).Normalize()) * sag;
    nc = Math.Abs(sag) < 1e-9 ? (Curve)Line.CreateBound(na, nb) : Arc.Create(na, nb, nm);
  } else nc = Line.CreateBound(na, nb);
  ce.SetGeometryCurve(nc, true);
  var s0 = inv.OfPoint(na); var s1 = inv.OfPoint(nb);
  report.Add(new { id = ce.Id.IntegerValue, type = c.GetType().Name, moved_mm = Math.Round(Math.Max(a.DistanceTo(na), b.DistanceTo(nb))*304.8,1), sE = Math.Round(s0.X*0.3048,3), sN = Math.Round(s0.Y*0.3048,3), eE = Math.Round(s1.X*0.3048,3), eN = Math.Round(s1.Y*0.3048,3), len_m = Math.Round(nc.Length*0.3048,3) });
}
return report;
